import{_ as a,o as r,c as t,a0 as o}from"./chunks/framework.BPYRhTv9.js";const y=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{"title":"Privacy Policy"},"headers":[],"relativePath":"legal/privacy.md","filePath":"legal/privacy.md"}'),s={name:"legal/privacy.md"};function i(n,e,l,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><em>Last updated: Jul 16, 2026</em></p><h3 id="data-we-collect" tabindex="-1">Data We Collect <a class="header-anchor" href="#data-we-collect" aria-label="Permalink to &quot;Data We Collect&quot;">​</a></h3><h4 id="content-you-create" tabindex="-1">Content You Create <a class="header-anchor" href="#content-you-create" aria-label="Permalink to &quot;Content You Create&quot;">​</a></h4><p>When you create a card, your text is sent to speech-to-text and AI tone rewriting services to process your request. We do not store your card text permanently on our servers. Only the metadata needed to display a shared card link (text, name, tone, palette) is stored temporarily alongside the card image. Cards are automatically deleted after a retention period (7 days for free users, 14 days for Pro users).</p><h4 id="email-subscriptions" tabindex="-1">Email Subscriptions <a class="header-anchor" href="#email-subscriptions" aria-label="Permalink to &quot;Email Subscriptions&quot;">​</a></h4><p>If you subscribe to occasion reminders, your email address is stored in our database and used only to send those reminders. You can unsubscribe at any time via the link in each email.</p><h4 id="error-monitoring-amp-session-replay" tabindex="-1">Error Monitoring &amp; Session Replay <a class="header-anchor" href="#error-monitoring-amp-session-replay" aria-label="Permalink to &quot;Error Monitoring &amp;amp; Session Replay&quot;">​</a></h4><p>We use Sentry to monitor application errors and improve reliability. Sentry collects error reports including the page URL, browser type, operating system, and stack trace when an error occurs. We also use Sentry Session Replay to record anonymized replays of user interactions (page navigation, clicks, scrolls, and form interactions) to help us understand how users experience the app and identify usability issues.</p><p>Session Replay does not capture keystrokes on password fields or other sensitive inputs. We have enabled data scrubbing to automatically redact sensitive information such as email addresses and credit card numbers. No personal data is intentionally collected beyond what is necessary for error diagnosis and usability analysis.</p><p>You can opt out of Sentry monitoring by enabling <strong>Do Not Track</strong> in your browser settings, or by using browser extensions that block Sentry scripts. See <a href="https://sentry.io/privacy/" target="_blank" rel="noreferrer">sentry.io/privacy</a> for Sentry&#39;s privacy policy.</p><h3 id="third-party-services" tabindex="-1">Third-Party Services <a class="header-anchor" href="#third-party-services" aria-label="Permalink to &quot;Third-Party Services&quot;">​</a></h3><p>Wibe Stories uses the following third-party services. Each service processes data according to its own privacy policy:</p><ul><li><strong>Deepgram</strong> — speech-to-text transcription</li><li><strong>OpenRouter</strong> — AI tone rewriting</li><li><strong>Vercel</strong> — hosting, blob storage, serverless functions</li><li><strong>Upstash</strong> — Redis data storage (usage limits, pro keys, email subscriptions)</li><li><strong>Neon</strong> — Postgres database (vault cards for Pro users)</li><li><strong>Resend</strong> — transactional emails (Pro key delivery, occasion reminders)</li><li><strong>Sentry</strong> — error monitoring and session replay (see above)</li></ul><h3 id="vault-access" tabindex="-1">Vault Access <a class="header-anchor" href="#vault-access" aria-label="Permalink to &quot;Vault Access&quot;">​</a></h3><p>We may access vault content only to investigate reported abuse, comply with legal obligations, or perform system maintenance necessary for platform operation. We will never access your vault for any other purpose.</p><h3 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h3><p>For questions about this policy, email <a href="mailto:yellowgreenlabs@proton.me?subject=Privacy%20Question" target="_blank" rel="noreferrer">yellowgreenlabs@proton.me</a>.</p>',18)])])}const h=a(s,[["render",i]]);export{y as __pageData,h as default};
